import os.path
import glob
import pandas as pd


IGNORED = '[\n'
SEPARATOR = ' : '
MULTILINE = '    \n'
END_OF_RECORDS = '  \n'


def get_files(ext='.raw'):
    path = input('RAW Files Folder path: ')
    pattern = os.path.join(path, '*{}'.format(ext))
    return glob.glob(pattern)


def parse_records(file):
    records = {}
    for line in file:
        if line.endswith(IGNORED):
            continue

        try:
            key, value = map(str.strip, line.split(SEPARATOR))
        except ValueError:
            # Not enought value to unpack
            continue
        else:
            records[key] = value

        if line.endswith(MULTILINE):
            multiline_value = [value]
            for line in file:
                multiline_value.append(line.strip())
                if not line.endswith(MULTILINE):
                    break
            records[key] = '\n'.join(multiline_value)

        if key == 'User_Header':
            multiline_value = [value]
            for line in file:
                multiline_value.append(line.strip())
                if line.endswith(END_OF_RECORDS)
                    break
            records[key] = '\n'.join(multiline_value)
            yield records
            records = {}


def parse_data(filename):
    with open(filename, 'r', encoding='latin-1') as f:
        yield from parse_records(f)


def parse_files(file_paths):
    for filename in file_paths:
        yield from parse_data(filename)


if __name__ == '__main__':
    files = get_files()
    records = list(parse_files(files))

    if files:
        print('Processed', len(files), 'files and found', len(records), 'records')
    else:
        print('No files found.')

    df = pd.DataFrame(records)

def sort(list_, lo=None, hi=None):
    if lo is None:
        lo = 0
    if hi is None:
        hi = len(list_)
    if hi - lo <= 1:
        return
    mid = lo + (hi - lo) // 2
    sort(list_, lo, mid)
    sort(list_, mid, hi)
    merge(list_, lo, mid, hi)

def merge(list_, lo, mid, hi):
    temp = list_[lo:mid]
    left = 0
    right = mid
    write = 0
    while left < mid - lo and right < hi:
        if list_[right] < temp[left]:
            list_[write] = list_[right]
            right += 1
        else:
            list_[write] = temp[left]
            left += 1
        write += 1
    if left < mid - lo
        list_[write:] = temp[left:]

def items(self):
    """
    Generator in the style of dict.items
    """
    curr = self.head.forward[0]
    while curr:
        yield (curr.key, curr.value)
        curr = curr.forward[0]

def __iter__(self):
    curr = self.head.forward[0]
    while curr:
        yield curr.key
        curr = curr.forward[0]

def move_to_top(stack, index):
    """Move element from index to top of stack."""
    stack.append(stack.pop(index))


def read_testcase(inputfile):
    """From inputfile read number of elements, and then stack it self."""

    stack_length = int(inputfile.readline())
    stack = [int(i) for i in inputfile.readline().split()]

    return stack_length, stack


def sort_dvds(stack_length, stack):
    """Sort DVD's by pulling elements larger than the top and put it top."""    
    previous_move_count = -1
    move_count = 0

    # Repeat until stack is sorted
    while previous_move_count != move_count:
        previous_move_count = move_count

        # Loop through from top till bottom, moving larger elements to top
        for index in xrange(stack_length-1, 0, -1):
            if stack[index - 1] > stack[-1]:
                move_to_top(stack, index - 1)
                move_count += 1

    return move_count


def main():

    with open("dvds.in") as inputfile:
        testcases = int(inputfile.readline())
        for _ in xrange(testcases):
            stack_length, stack = read_testcase(inputfile)

            moves_needed = sort_dvds(stack_length, stack)
            print("{}".format(moves_needed))


if __name__ == '__main__':  
    main()

