from Edge import Edge

class Graph:
    def __init__(self, nodes=[], edges=set()):
        self.nodes = nodes
        self.edges = edges

    def addNode(self, node, nodeIndex):
        node.index = nodeIndex
        self.nodes.append(node)

    def addEdge(self, sourceNodeIdx, targetNodeIdx):
        edge = Edge(sourceNodeIdx, targetNodeIdx)
        self.edges.add(edge)

def roundrobin(*iterables):
    # took from here https://docs.python.org/3/library/itertools.html#itertools-recipes

    "roundrobin('ABC', 'D', 'EF') --> A D E B F C"
    # Recipe credited to George Sakkis

    pending = len(iterables)
    nexts = cycle(iter(it).__next__ for it in iterables)
    while pending:
        try:
            for next in nexts:
                yield next()
        except StopIteration:
            pending -= 1
            nexts = cycle(islice(nexts, pending))

