    # Get "email" and "password"
    email = userInfo.get('email')
    password = userInfo.get('password')     
    if email is None or password is None:                                                                                                                       
        errorsList.append(Error("email/password","Email or Password not entered"))
        return make_error(MainError('400','Incorrect Input',errorsList))

    # Check password meets criteria
    if len(password) > 1024:
        errorsList.append(Error("password","Password maximum length is 1024 characters")) 
    if len(password) < 8:
        errorsList.append(Error("password","Password must be at least 8 characters"))


    # Check email meets criteria
    email = email.strip()
    # Check if email address is valid (syntactically)
    match = re.match("[^@]+@[^@]+\.[^@]+", email)
    if match is None:
        errorsList.append(Error("email","Not a valid email address"))
    # Check if email address is already in database
    with contextlib.closing(DBSession()) as session:        
        try:
            if session.query(USER).filter_by(USERSEMAIL=email).count():
                errorsList.append(Error("email","This email address already exists"))
        except Exception as error:
            session.rollback()
            logger = logging.getLogger('__name__')
            logger.error(error)
            errorsList.append(Error("database","An error occurred with the database. Please try again later."))
            return make_error(MainError('500','Database error',errorsList))


    # If errors exist, return all errors
    if errorsList:
        return make_error(MainError('400','Incorrect Input',errorsList))

    # Add user to database      
    user = USER(email, password)        
    with contextlib.closing(DBSession()) as session:            
        try:
            session.add(user)
            session.commit()
        except Exception as error:
            session.rollback()
            logger = logging.getLogger('__name__')
            logger.error(error)
            errorsList.append(Error("database","An error occurred with the database. Please try again later."))
            return make_error(MainError('500','Database error',errorsList))
        return jsonify(data=user.serialize())

def make_error(mainError):
    response = jsonify(data=mainError.serialize())
    response.status_code = int(mainError.code)
    return response

class MainError:
    def __init__(self, code, message, errorsList):          
        self.code = code
        self.message = message
        # List of Error objects
        self.errorsList = errorsList

def serialize(self):  
    return {           
    'errorCode': self.code, 
    'message': self.message,
    'errorList': [error.serialize() for error in self.errorsList],
    'success': 'false'
    }

import functools

# https://stackoverflow.com/a/28961925/321973
def property_if_None_generator(f, cached=False):
    @functools.wraps(f)
    def wrapped(self):
        value = self.__getattribute__('_' + f.__name__)
        if value is not None:
            return value
        else:
            return f(self)
    if cached:
        wrapped = functools.lru_cache()(wrapped)
    return property(wrapped)

property_if_None = lambda f: property_if_None_generator(f, cached=False)
cached_property_if_None = lambda f: property_if_None_generator(f, cached=True)

class Line:
    @property
    def angle(self):
        try:
            return self._angle
        except AttributeError:
            self._angle = math.atan2(self.end.y - self.start.y, self.end.x - self.start.x)
            return self._angle

    @property
    def length(self):
        try:
            return self._length
        except AttributeError:
            self._length = math.sqrt((self.end.x - self.start.x) ** 2 + (self.end.y - self.start.y) ** 2)
            return self._length

    def rotate(self, pivot_point, angle):
        self.start.rotate(pivot_point, angle)
        self.end.rotate(pivot_point, angle)
        self._reset_attributes(['_angle'])

    def scale(self, pivot_point, factor):
        self.start.scale(pivot_point, factor)
        self.end.scale(pivot_point, factor)
        self._reset_attributes(['_length'])

    def _reset_attributes(self, attributes):
        for attribute in attributes:
            try:
                delattr(self, attribute)
            except:
                pass

class DummyUpdater(object):

    def from_dict(self, d):
        self.__dict__.update(d)
        return self

    def __repr__(self):
        attributes = inspect.getmembers(self.__class__, lambda a: not(inspect.isroutine(a)))
        return '{}'.format({a[0]: getattr(self, a[0]) for a in attributes if not(a[0].startswith('__') and a[0].endswith('__'))})


