def __str__(self):
    """Return formatted grid."""
    BOLD = '\033[1m'
    ENDC = '\033[0m'

    fill_mask = np.sum(self.mask, axis=2) == 1

    top_line = '┏' + ('━━┯' * 2 + '━━┳') * 2 + '━━┯' * 2 + '━━┓'
    mid_line = '┣' + ('━━┿' * 2 + '━━╋') * 2 + '━━┿' * 2 + '━━┫'
    bot_line = '┗' + ('━━┷' * 2 + '━━┻') * 2 + '━━┷' * 2 + '━━┛'
    div_line = '┠' + ('──┼' * 2 + '──╂') * 2 + '──┼' * 2 + '──┨'
    num_line = '┃ {}│ {}│ {}' * 3 + '┃'

    counter = 1
    lines = [top_line]
    for row_index, row in enumerate(self.grid):
        line_to_print = []
        for col_index, cell in enumerate(row):
            if fill_mask[row_index, col_index] == 1:
                line_to_print.append(BOLD + str(cell) + ENDC)
            elif cell == 0:
                line_to_print.append(' ')
            else:
                line_to_print.append(str(cell))
        lines.append(num_line.format(*line_to_print))
        if (counter % 3 == 0) and counter < 9:
            lines.append(mid_line)
        elif counter < 9:
            lines.append(div_line)
        counter += 1
    lines.append(bot_line)
    return "\n".join(lines)

import webbrowser

import rfc3987

def open_links(links):
    links = (
        link
        for link in links
        if rfc3987.match(link, rule='IRI') is not None
    )
    # Get default webbrowser, change if you want to force a specific browser
    browser = webbrowser.get()
    try:
        browser.open_new(next(links))
    except StopIteration:
        pass
    else:
        for link in links:
            browser.open_new_tab(link)

