def IsPalindrome(s):
    m = int(len(s) / 2)

    str1 = s[:m]
    str2 = s[m:][::-1]

    if(len(s) % 2 != 0):
        str2 = s[m + 1:][::-1]

    if(str1 != str2):
        return False

    return True

