def parse_condition(tokens):
    """Parse a condition given by an iterator of tokens, and return a
    parse tree.

    >>> tokens = tokenize_condition("((dog OR cat) AND *Horse*)")
    >>> parse_condition(tokens)
    BinOp(left=BinOp(left='dog', op='OR', right='cat'), op='AND', right=IgnoreCase(body='Horse'))

    """
    token = next(tokens)           # The current token.

    def error(expected):
        # Current token failed to match, so raise syntax error.
        raise SyntaxError("Expected {} but found {!r}"
                          .format(expected, token))

    def match(*valid_tokens):
        # If the current token is found in valid_tokens, consume it
        # and return True. Otherwise, return False.
        nonlocal token
        if token in valid_tokens:
            token = next(tokens)
            return True
        else:
            return False

    def term():
        # term ::= ( binop ) | * binop * | WORD
        if match('('):
            tree = binop()
            if match(')'):
                return tree
            else:
                error("')'")
        elif match('*'):
            tree = binop()
            if match('*'):
                return IgnoreCase(tree)
            else:
                error("'*'")
        elif token in (')', 'AND', 'OR'):
            error("term")
        else:
            t = token
            match(token)
            return t

    def binop():
        # binop ::= term | term OR term | term AND term
        left = term()
        op = token
        if match('AND', 'OR'):
            right = term()
            return BinOp(left, op, right)
        else:
            return left

    tree = binop()
    if token != TOKEN_END:
        error("end of input")
    return tree

import itertools

def byte_gen(iterable, chunk=1024):
    while True:
        ret = bytearray(islice(iterable, chunk))
        if not ret:
            break
        yield from ret


def grouper(iterable, n, fillvalue=None):
    "Collect data into fixed-length chunks or blocks"
    # grouper('ABCDEFG', 3, 'x') --> ABC DEF Gxx"
    args = [iter(iterable)] * n
    return itertools.zip_longest(*args, fillvalue=fillvalue)


def hex_iter_changer(iterable, base_addr=0, start=0, stop=None, chunk=1024):
    sliced = itertools.islice(iterable, start, stop)
    byte_slice = byte_gen(sliced)
    empty_prefix = itertools.repeat(None, base_addr + start)
    return itertools.chain(empty_prefix, byte_slice)


def _hexdump_generator(iterable, base_addr=0, start=0, stop=None, width=16, sep='\b'):
    iterable = hex_iter_changer(iterable, base_addr, start, stop)
    groups = grouper(iterable, width)
    for index, group in zip(itertools.count(0, width), groups):
        group = list(group)
        yield (
            index,
            [
                None if byte is None else format(byte, '02X')
                for byte in group
            ],
            [
                None if byte is None else chr(byte)
                for byte in group
            ]
        )


def hexdump_generator(iterable, base_addr=0, start=0, stop=None, width=16, sep='\b'):
    middle = width // 2
    for index, hex_values, values in _hexdump_generator(iterable, base_addr, start, stop, width, sep):
        hex_values = ['  ' if byte is None else byte for byte in hex_values]
        hex_values.insert(middle, sep)
        values = [' ' if char is None else char for char in values]
        yield '{:08X}   {}  {}'.format(index, ' '.join(hex_values), ''.join(values))


def compress_hexdump_generator(iterable, base_addr=0, start=0, stop=None, width=16, sep='\b'):
    prev = ''
    duplicates = 0
    for row in hexdump_generator(iterable, base_addr, start, stop, width, sep):
        if prev.split()[1:] == row.split()[1:]:
            if not duplicates:
                yield '*'
            duplicates += 1
        else:
            yield row
            duplicates = 0
        prev = row
    if duplicates:
        yield prev

class Stack():

    def __init__(self):
        self.element_stack = []
        self.min_element_stack = []

    def push(self, item):
        if self.size() == 0:
            self.min_element_stack.append(item)
        else:
            self.min_element_stack.append(min(self.min_element_stack[self.size() - 1], item))
        self.element_stack.append(item)

    def pop(self):
        if self.is_empty():
            raise ValueError('Empty stack')
        self.min_element_stack.pop()
        return self.element_stack.pop()

    def minimum(self):
        if self.is_empty():
            raise ValueError('Empty stack')
        return self.min_element_stack[self.size() - 1]

    def is_empty(self):
        return self.size() == 0

    def size(self):
        return len(self.element_stack)


def main():
    stack = Stack()
    stack.push(3)
    print(stack.minimum())
    stack.push(5)
    print(stack.minimum())
    stack.push(1)
    print(stack.minimum())
    stack.pop()
    print(stack.minimum())

if __name__ == "__main__":
    main()

memo = {}                               # initialize the memo dictionary
def collatz_seq(n):
    if not n in memo:                   # check if already computed
        if n == 1:                      # if not compute it
            memo[n] = 1                 # cache it
        elif n % 2 == 0:
            memo[n] = collatz_seq(n // 2) + 1
        else:
            memo[n] = collatz_seq(3*n + 1) + 1
    return memo[n]                      # and return it

import requests
from lxml import html


class YellowPageScraper:
    base_url = "https://www.yellowpages.com/search?search_terms=pizza&geo_location_terms=Los+Angeles%2C+CA"
    url = "https://www.yellowpages.com"

    def __init__(self):
        self.vault = []
        self.session = requests.Session()

    def crawl(self):
        self.get_urls(self.base_url)
        self.process_links(self.base_url)

    def get_urls(self, link):
        """Going to the main page for collecting links leading to the target page."""
        response = self.session.get(link)
        tree = html.fromstring(response.text)

        for item in tree.xpath("//div[@class='info']"):
            item_links = item.xpath(".//a[@class='business-name'][not(@itemprop='name')]/@href")
            for page in item_links:
                self.target_page(self.url + page)

    def process_links(self, link):
        """Creating links leading to the next page."""
        response = self.session.get(link)
        tree = html.fromstring(response.text)

        next_urls = tree.xpath("//div[@class='pagination']//li/a/@href")
        for next_url in next_urls:
            self.get_urls(self.url + next_url)

    def target_page(self, urls):
        """Scraping required data reaching this target page."""
        response = self.session.get(urls)
        tree = html.fromstring(response.text)

        for post in tree.xpath("//*[@id='main-header']"):
            name = post.findtext(".//div[@class='sales-info']/h1")
            phone = post.findtext('.//p[@class="phone"]')

            records = name, phone
            if records not in self.vault:
                self.vault.append(records)

    def __str__(self):
        return self.vault


if __name__ == '__main__':
    crawler = YellowPageScraper()
    crawler.crawl()
    for item in crawler.vault:
        print(item)

from typing import Any, Dict, Iterator

class Task:
    def __init__(self, data: Dict[Any, Any]) -> None:
        self.data = data

    @property
    def id(task) -> str:
        if task.get('due') and task.get('description'):
            return task['due'] + task['description']
        return task['uuid']

    @property
    def is_valid(self) -> bool:
        if self.data['status'] in invalid_statuses_for_calendar:
            return False

        if not (self.data.get('status') or self.data['status'] in valid_statuses_for_calendar):
            return False
        return True

    @property
    def first_calendar(self) -> str:
        if self.data.get('tags') is None:
            return ""
        cal = next((s for s in self.data['tags'] if 'cal.' in s), None)
        if cal is None:
            return ""
        return cal.replace("cal.", "")

    @property
    def start_date_for_event(self) -> str:
        if self.data.get('due'):
            return self.data['due']
        if self.data.get('scheduled'):
            return self.data['scheduled']
        if self.data.get('wait'):
            return self.data['wait']
        else:
            return ""

    def __str__(self):
        project = "{} {} {}".format("[", self.data['project'], "] ") if self.data.get('project') else ""
        tags = " [" + ", ".join([k for k in self.data['tags'] if 'cal.' not in k]) + "]" if (self.data.get('tags') and [k for k in
            self.data['tags'] if 'cal.' not in k]) else ""
        return project + self.data['description'] + tags

    def __eq__(self, other):
        if isinstance(other, Task):
            return self.id == other.id
        return NotImplemented

    def __hash__(self):
        return hash(self.id)


