def score_arbitrary(dice_roll: list):
    dice_roll = collections.Counter(dice_roll)

#     define the scores
#     the allowed_sets are tuples
    set_scores = {(i,) * 3: i*100 for i in range(2, 7)}
    set_scores[(1, 1, 1,)] = 1000
    set_scores[(2, 3, 4,)] = 999
    dice_score = {1:100, 5: 50}

    sets, remaining_dice = search_arbitrary_sets(dice_roll, set_scores)

    set_total = sum(set_scores.get(dice_set, 0) * count for dice_set, count in  sets.items())
    remaining_total = sum(dice_score.get(dice, 0) * count for dice, count in  remaining_dice.items())

    return set_total + remaining_total

def dice_rolls_contains(dice_rolls: dict, dice_set: dict):
    return all(dice_rolls.get(key, 0) >= dice_set[key] for key in dice_set)

def search_arbitrary_sets(dice_rolls: dict, allowed_sets):
    sets_found = collections.Counter()
    remaining_dice = collections.Counter(dice_rolls)
    for dice_set in allowed_sets:
        while dice_rolls_contains(remaining_dice, collections.Counter(dice_set)):
            sets_found[dice_set] += 1
            remaining_dice -= collections.Counter(dice_set)
    return sets_found, remaining_dice

import re
import string
import itertools

TRANS = string.maketrans('acgu', 'tgca')
CONVS = {'a': 'g', 'c': 't'}

SEEDS = [
    "6mer",
    "7mer",
    "7A1",
    "8mer"
]


def create_compliments(rna):
    rna = rna.translate(TRANS)
    yield rna
    all_indexes = [i for i, c in enumerate(rna) if c in CONVS]
    rna = list(rna)
    for n in (1, 2):
        for indexes in itertools.combinations(all_indexes, n):
            t = rna[:]
            for index in indexes:
                t[index] = CONVS[t[index]]
            yield ''.join(t)


def grouper(iterable, n, fillvalue=None):
    "Collect data into fixed-length chunks or blocks"
    # grouper('ABCDEFG', 3, 'x') --> ABC DEF Gxx"
    args = [iter(iterable)] * n
    return itertools.izip_longest(*args, fillvalue=fillvalue)


def check_for_match(mi_RNAs, seed, mi_RNA_name, m_RNA_list):
    mi_RNAs = list(mi_RNAs)
    for m_RNA_name, m_RNA in grouper(m_RNA_list, 2):
        m_RNA_name = m_RNA_name[14:m_RNA_name.find(" ", 15)]
        for entry in mi_RNAs:
            matches = [m.start() for m in re.finditer(entry, m_RNA)]
            if matches:
                all_indices = tuple(
                    (match, match + len(entry))
                    for match in matches
                )
                yield mi_RNA_name, m_RNA_name, seed, all_indices


def prepare_for_match(mi_RNA, mi_RNA_name, m_RNA_list):
    mi_RNAs = [
        mi_RNA[1:7][::-1],
        mi_RNA[1:8][::-1],
        mi_RNA[:7][::-1],
        mi_RNA[0:9][::-1]
    ]

    for mi_RNA, seed in zip(mi_RNAs, SEEDS):
        for entry in check_for_match(create_compliments(mi_RNA), seed, mi_RNA_name, m_RNA_list):
            yield entry


def main():
    mi_RNA_list = open('miRNA_list.txt').read().splitlines()
    m_RNA_list = open('mRNA_list.txt').read().splitlines()

    for index in range(1, len(mi_RNA_list), 2):
        mi_RNA_name = mi_RNA_list[index-1][5:mi_RNA_list[index-1].find(' ')]
        if (len(mi_RNA_list[index]) < 8):
            print "{} at {} has insufficient length.".format(mi_RNA_name, index)
        else:
            for entry in prepare_for_match(mi_RNA_list[index].lower(), mi_RNA_name, m_RNA_list):
                print tuple(entry)


if __name__ == '__main__':
    main()

import re
import random
import sys

# load the PREDEFINED from an external file
with open('predefined.txt') as predefined_file:
    PREDEFINED = dict(line.strip().split(' ', 1) for line in predefined_file)

# regular expression matches the various versions of rolls
ROLL_EXP = re.compile(r'(?:H(\d+),)?(\d+)d(\d+|F)')
#                        H(keep),(dice)d(sides)
def handle_roll(match):
    """
    Handle the rolls matched by ROLL_EXP
    """
    keep, dice, number = match.groups()

    # massage the data
    dice = int(dice)

    # if keep is None means that There is not (H3,) section
    if keep is None:
        keep = dice
    else:
        keep = int(keep)

    # F indicates a fudge die, 
    if number == 'F':
        roll = [random.randint(-1, 1) for x in xrange(dice)]
    else:
        roll = [random.randint(1, int(number)) for x in xrange(dice)]

    # sum up the remaining die
    roll.sort(reverse = True)
    return sum(roll[:keep])

# making the constant
CONSTANT = re.compile(r'-?\d+')
def handle_constant(match):
    # just use python's builtin int to understand the number
    return int(match.group(0))

# store a list of possible methods
METHODS = [
    (ROLL_EXP, handle_roll),
    (CONSTANT, handle_constant),
]

class BadRoll(Exception):
    """
    This exception is thrown to indicate a failure to understand what the user 
    specified
    """

def parse_roll(argument):
    """
    Given a basic roll, either return the summation or raise a BadRoll
    """
    for method_re, method_handler in METHODS:
        # try to match it
        match = method_re.match(argument)
        if match is not None:
            return method_handler(match) 
    else:
        raise BadRoll(argument)

def handle_argument(argument):
    """
    Return the summation of described rolls
    """
    # continually lookup up the argument in PREDEFINED
    # until we find nothing, then use parse_roll
    while True:
        try:
            argument = PREDEFINED[argument]
        except KeyError:
            return parse_roll(argument)




def main(args):
    try:
        # sum up the description of the arguments
        print sum(map(handle_argument, args[1:]))
    except BadRoll as error:
        # print what we didn't understand
        print >> sys.stderr, "Did not understand:", str(error)

if __name__ == '__main__':
    main(sys.argv)

def triples(self, (s, p, o)):
    try:
        args = (int(s != None), int(p != None), int(o != None))

        if args in [(1, 1, 1), (1, 1, 0), (1, 0, 0), (0, 0, 0)]:
            lookat  = self._spo
            a1 = s; a2 = p; a3 = o;
            invperm = [0, 1, 2]
        if args in [(0, 1, 1), (0, 1, 0)]:
            lookat = self._pos
            a1 = p; a2 = o; a3 = s;
            invperm = [2, 0, 1]
        if args in [(1, 0, 1), (0, 0, 1)]:
            lookat = self._osp
            a1 = o; a2 = s; a3 = p;
            invperm = [1, 2, 0]

        permute = lambda x, p: (x[p[0]], x[p[1]], x[p[2]])

        if sum(args) == 3:
            #if a3 in lookat[a1][a2]: #See sindikat's comment below
            #   yield permute((a1, a2, a3), invperm)
            return iter([permute((a1, a2, a3), invperm)] if a3 in lookat[a1][a2] else [])
        if sum(args) == 2:
            return (permute((a1, a2, ra3), invperm) for ra3 in lookat[a1][a2])
        if sum(args) == 1:
            return (permute((a1, ra2, ra3), invperm) for ra2, a3set in lookat[a1].items() for ra3 in a3set)
        if sum(args) == 0:
            return (permute((a1, a2, a3), invperm) for ra1, a2set in lookat.items() for ra2, a3set in a2set.items() for ra3 in a3set)
    except KeyError:
        pass

