def apply_filter(lbuf):
    parsed = parse_line(lbuf)
    if filter(parsed):
        return [parsed]
    else
        return []

def get_filtered_lines(source):
    filtered_lines = []
    collected = ""
    for line in source:
        if line.startswith('[') and collected:
            filtered_lines.extend(apply_filter(collected))
            collected = ""
        collected += line
    filtered_lines.extend(apply_filter(collected))
    return filtered_lines

import doctest

def egcd(a, b):
    """
    Meaningful description here...

    >>> egcd(4132, 434)
    (2, -48, 457)
    """

    if a == 0:
        return (b, 0, 1)

    g, y, x = egcd(b % a, a)
    return (g, x - (b // a) * y, y)



doctest.testmod()

def pyramid(height):
    FMT = '%3s'
    def row(r):
        right_half = [FMT % num for num in range(2, 2 + r)] + \
                     [FMT % ' ' for spc in range(2 + r, 1 + height)]
        return ''.join(list(reversed(right_half)) + # Mirrored right half
                       [FMT % 1] +                  # Center
                       right_half)                  # Right half
    return "\n".join([row(r) for r in range(height)])

