import os
import operator
import sys
import MySQLdb

def Connect():
  return MySQLdb.connect(host='localhost', user='rohit', passwd='bloodline', db='Twitter')

def FiftyPlus(conn):
  with conn as cursor:
    cursor.execute('SELECT username FROM users WHERE no_tweets > 50')
    return map(operator.itemgetter(0), cursor.fetchall())


def Tweets(conn, name):
  with conn as cursor:
    cursor.execute('SELECT tweets FROM tweets WHERE username = %s', (name,))
    return map(operator.itemgetter(0), cursor.fetchall())


def WriteUserTweets(base_dir, username, tweets):
  with file(os.path.join(base_dir, username), 'w') as user_tweet_log:
    for tweet in tweets:
      user_tweet_log.write(tweet + '\n')


def main():
  root_dir = sys.argv[1]
  conn = Connect()
  for user in FiftyPlus(conn):
    tweets = Tweets(conn, user)
    WriteUserTweets(root_dir, user, tweets)

def main(n):
    """return the largest palindrome of products of `n` digit numbers"""
    largest = 10 ** n - 1
    for a in xrange(largest, int(.9 * largest), -1):
        for b in xrange(a, int(.9 * a), -1):
            if is_palindrome(a * b):
                return a, b, a * b

def is_palindrome(number):
    number = str(number)
    halfway = len(number) // 2
    return number[:halfway] == number[:-halfway - 1:-1]

if __name__ == '__main__':
    print main(3)

class Cell(object):
  def __init__(self, data, next=None):
    self.data = data
    self.next = next

def create_list(length=1):
  linked_list = Cell(0)
  head = linked_list
  for prefill_value in xrange(1, length):
    head.next = Cell(prefill_value)
    head = head.next
  return linked_list

