def detectLeapyear(in_year):

    rem4 = in_year % 4
    if not rem4:
        rem100 = in_year % 100
        if not rem100:
            rem400 = in_year % 400
            if not rem400:
                return 1
            else:
                return 0
        else:
            return 1
    else:
        return 0

def get_simple_type(element):
    return {
        element.get("name"): {
            "restriction": element.getchildren()[0].attrib,
            "elements": [ e.get("value") for e in element.getchildren()[0].getchildren() ]
        }
    }

